const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountFuji = ee.Geometry.Point([138.7292, 35.3606]);
  const region = mountFuji.buffer(10000); // 10 km radius around Mount Fuji

  const date2019_start = '2019-12-01';
  const date2019_end = '2019-12-31';
  const date2020_start = '2020-12-01';
  const date2020_end = '2020-12-31';

  // Sentinel-2 L2A collection (Surface Reflectance)
  const S2_SR_COLLECTION = 'COPERNICUS/S2_SR';

  // Function to mask clouds using the SCL band
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    // Clouds, cloud shadows, and saturated pixels (values 3, 6, 8, 9, 10)
    const cloudMask = scl.eq(3).or(scl.eq(6)).or(scl.eq(8)).or(scl.eq(9)).or(scl.eq(10)).not();
    return image.updateMask(cloudMask);
  }

  // Function to calculate NDSI and add it as a band
  function addNdsi(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    return image.addBands(ndsi);
  }

  // Function to process image collection for a given year
  async function processCollection(yearStart, yearEnd, yearLabel) {
    let collection = ee.ImageCollection(S2_SR_COLLECTION)
      .filterBounds(region)
      .filterDate(yearStart, yearEnd)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Initial cloud filter

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`No images found for ${yearLabel}.`);
      return { ndsiMean: null, pixelCount: 0, imageSize: 0 };
    }

    collection = collection
      .map(maskS2clouds)
      .map(addNdsi)
      .select('NDSI'); // Select only the NDSI band

    // Mosaic the collection to get a single image (e.g., median composite)
    // Using a median composite to reduce noise and cloud effects further.
    const composite = collection.median();

    if (composite.bandNames().size().getInfo() === 0) {
      console.log(`No valid bands after processing for ${yearLabel}.`);
      return { ndsiMean: null, pixelCount: 0, imageSize: 0 };
    }

    // Calculate valid pixels for the composite image
    const pixelCount = await composite.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 100, // Use native resolution for pixel count, but a larger scale for mean
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels after cloud masking for ${yearLabel}.`);
      return { ndsiMean: null, pixelCount: 0, imageSize: initialSize };
    }

    // Calculate mean NDSI over the region
    const meanNdsi = await composite.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000, // Use a larger scale for mean to avoid memory issues and speed up
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    console.log(`${yearLabel} Images: ${initialSize} (Val Pixels: ${pixelCount})`);
    return { ndsiMean: meanNdsi, pixelCount: pixelCount, imageSize: initialSize };
  }

  // Process data for 2019
  const result2019 = await processCollection(date2019_start, date2019_end, '2019 Dec');
  const ndsi2019 = result2019.ndsiMean;
  const pixels2019 = result2019.pixelCount;
  const images2019 = result2019.imageSize;

  // Process data for 2020
  const result2020 = await processCollection(date2020_start, date2020_end, '2020 Dec');
  const ndsi2020 = result2020.ndsiMean;
  const pixels2020 = result2020.pixelCount;
  const images2020 = result2020.imageSize;

  // 5. Validation & Final Answer
  if (images2019 === 0 || images2020 === 0) {
    console.log("C1"); // Empty Collection
    return;
  }

  if (pixels2019 === 0 || pixels2020 === 0) {
    console.log("C2"); // No Valid Pixels after masking
    return;
  }

  if (ndsi2019 === null || ndsi2019 === undefined || isNaN(ndsi2019) ||
      ndsi2020 === null || ndsi2020 === undefined || isNaN(ndsi2020)) {
    console.log("C3"); // Calculation failure
    return;
  }

  console.log(`Mean NDSI 2019: ${ndsi2019.toFixed(4)}`);
  console.log(`Mean NDSI 2020: ${ndsi2020.toFixed(4)}`);

  if (ndsi2020 < ndsi2019) {
    console.log("A"); // Yes, lower in 2020
  } else {
    console.log("B"); // No, not lower in 2020
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
